<?php
require_once __DIR__ . '/../../bootstrap.php';
$u=require_auth(['super_admin','owner','admin','manager']);$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
if($method==='GET'){$bid=business_scope($u,(int)($_GET['business_id']??0));$st=db()->prepare('SELECT * FROM gmb_services_workspace WHERE business_id=? ORDER BY is_active DESC,name');$st->execute([$bid]);json_response(['ok'=>true,'services'=>$st->fetchAll()]);}
require_method('POST');require_csrf();$d=request_json();$bid=business_scope($u,(int)($d['business_id']??0));$items=$d['services']??[];if(!is_array($items))json_response(['ok'=>false,'error'=>'services must be an array'],422);$pdo=db();$pdo->beginTransaction();try{$up=$pdo->prepare("INSERT INTO gmb_services_workspace(business_id,name,description,price_text,is_active) VALUES(?,?,?,?,1) ON DUPLICATE KEY UPDATE description=VALUES(description),price_text=VALUES(price_text),is_active=1");foreach($items as $item){$name=trim((string)($item['name']??''));if($name==='')continue;$up->execute([$bid,$name,trim((string)($item['description']??''))?:null,trim((string)($item['price_text']??''))?:null]);}$pdo->commit();audit((int)$u['id'],$bid,'gmb_services_saved',['count'=>count($items)]);}catch(Throwable $e){$pdo->rollBack();throw $e;}json_response(['ok'=>true]);
